       numbers congruent to 1 or 6 mod 7 that cannot be written
       as a product of smaller Monday-Saturday numbers. */
    for (int i = 2; i <= MAXN; i++) {
        if (!is_ms(i)) continue;
        if (spf[i] == 0) {
            spf[i] = i; /* i is a Monday-Saturday prime */
            if ((long long)i * i <= MAXN) {
                for (int j = i * i; j <= MAXN; j += i) {
                    if (is_ms(j) && spf[j] == 0) spf[j] = i;
                }
            }
        }
    }

    int n;
    while (scanf("%d", &n) == 1) {
        int x = n;
        int factors[32];
        int cnt = 0;

        while (x > 1) {
            int p = spf[x];
            if (p == 0) p = x; /* safety, though for valid input this should not happen */
            factors[cnt++] = p;
            while (x % p == 0) x /= p;
        }

        /* factors are already in ascending order */
        printf("%d:", n);
        for (int i = 0; i < cnt; i++) {
            printf(" %d", factors[i]);
        }
        printf("\n");
    }

    return 0;
