import sys

def is_ms(n: int) -> bool:
    return n % 7 in (1, 6)

def ms_prime_factors(n: int):
    factors = []
    x = n
    d = 2
    while d * d <= x:
        if x % d == 0:
            if is_ms(d):
                factors.append(d)
            while x % d == 0:
                x //= d
        d += 1
    if x > 1 and is_ms(x):
        factors.append(x)
    return factors

def main():
    data = list(map(int, sys.stdin.read().split()))
    out = []
    for n in data:
        if n == 1:
            break
        factors = ms_prime_factors(n)
        out.append(f"{n}:" + "".join(f" {p}" for p in factors))
    sys.stdout.write("\n".join(out))

