public class MondaySaturdayPrimeFactors {

    // Precompute Monday-Saturday primes up to 300000 using sieve
    static List<Integer> getMSP(int limit) {
        boolean[] isPrime = new boolean[limit + 1];
        Arrays.fill(isPrime, true);
        isPrime[0] = isPrime[1] = false;

        // Standard sieve for all numbers
        for (int i = 2; i * i <= limit; i++) {
            if (isPrime[i]) {
                for (int j = i * i; j <= limit; j += i) {
                    isPrime[j] = false;
                }
            }
        }

        List<Integer> msPrimes = new ArrayList<>();
        for (int i = 2; i <= limit; i++) {
            if (isPrime[i]) {
                int rem = i % 7;
                if (rem == 1 || rem == 6) {
                    msPrimes.add(i);
                }
            }
        }
        return msPrimes;
    }

    // Check if a number is a Monday-Saturday number
    static boolean isMS(int n) {
        int rem = n % 7;
        return rem == 1 || rem == 6;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;

        // Precompute Monday-Saturday primes up to 300000
        List<Integer> msPrimes = getMSP(300000);

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) continue;
            int n = Integer.parseInt(line);
            if (n <= 1) continue;
            if (!isMS(n)) continue; // Should not happen per problem statement

            List<Integer> factors = new ArrayList<>();
            int temp = n;

            for (int p : msPrimes) {
                if (p * p > temp) break;
                if (temp % p == 0) {
                    factors.add(p);
                    while (temp % p == 0) {
                        temp /= p;
                    }
                }
            }

            // If remaining temp is a Monday-Saturday prime > 1
            if (temp > 1 && isMS(temp)) {
                factors.add(temp);
            }

            // Output format: number: factor1 factor2 ...
            StringBuilder sb = new StringBuilder();
            sb.append(n).append(":");
            for (int f : factors) {
                sb.append(" ").append(f);
            }
            System.out.println(sb.toString());
        }
    }
}

